"""Controlled C# editor drafts; real DOM, simulated metadata, no compiler claims."""
import http.server,json,pathlib,sys,tempfile,threading
from playwright.sync_api import sync_playwright,expect

repo=pathlib.Path(sys.argv[1]).resolve();case=pathlib.Path(tempfile.mkdtemp(prefix='confectory-private-node-ref-value-renderer-'));checks=[];errors=[]
class Handler(http.server.SimpleHTTPRequestHandler):
 def __init__(self,*a,**kw):super().__init__(*a,directory=str(repo),**kw)
 def log_message(self,*a):pass
server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);threading.Thread(target=server.serve_forever,daemon=True).start()
bootstrap=r"""async()=>{
 const {createFeatureAuthoring}=await import('/examples/editor-home/ui/feature-authoring.js');
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
 const contract={args:[{name:'amount',type:'long'},{name:'count',type:'long'}],return:'long'},native={args:[{name:'firstNative',type:'long'},{name:'secondNative',type:'long',mode:'ref'}],return:'long'};
 const text='return Keep(firstNative+secondNative); // 한글 😀\r\n',helpers='static long Keep(long value){return value;}\r\n',row={hash:'a'.repeat(64),sourceKind:'scoped-code-csharp',caller:true,editableNativeNames:false,editableNativeTypes:[],removableNativeInputs:[],editableNativeOrder:false,editableNativeRefs:[{name:'secondNative',local:'ref_counter',label:'기존 참조 저장소'}],control:'next',helperEditor:true,signature:native,contractSignature:native,text,helpers,path:'private.node.json',whole:{node:'inner/body',hash:'b'.repeat(64)}},state={saved:{},drafts:JSON.parse(sessionStorage.aliasDrafts||'{}'),commits:[],toasts:[]};
 const controller=createFeatureAuthoring({$,$$,esc,authorInputs:new Map(),toast:t=>state.toasts.push(t),modal:(title,html,mount)=>{const root=document.createElement('section');root.setAttribute('role','dialog');root.innerHTML=html;document.body.append(root);mount(root,()=>root.remove());}});
 globalThis.fixture={state,row,contract,text,helpers,open:()=>controller.editInformationBodies({title:'부모 프레임 보존',rows:{body:row},contract,alive:()=>true,saved:state.saved,drafts:state.drafts,retain:(id,v)=>{state.drafts[id]=v;sessionStorage.aliasDrafts=JSON.stringify(state.drafts);},cancel:()=>{},commit:(id,v)=>state.commits.push(v)}),drop:()=>document.querySelector('[role=dialog]')?.remove()};
}"""
def checked(label):checks.append(label);print('PASS '+label,flush=True)
def header():return page.locator('[data-code-source]').input_value().split('\n{',1)[0]
def body(text):
 field=page.locator('[data-code-source]');field.evaluate('(el)=>{const s=[...el.closest(".bp-script-editor").querySelectorAll("[data-code-highlight]>span")],b=s.find(v=>v.dataset.codeRegion==="body"),start=s.slice(0,s.indexOf(b)).reduce((n,v)=>n+v.textContent.length,0);if(!b)throw Error("missing body");el.focus();el.setSelectionRange(start,start+b.textContent.length)}');page.keyboard.insert_text(text)
def parameters(text):
 field=page.locator('[data-code-source]');field.evaluate("el=>{el.focus();el.setSelectionRange(el.value.indexOf('(')+1,el.value.indexOf(')'));}");page.keyboard.insert_text(text)
try:
 with sync_playwright()as p:
  expect.set_options(timeout=10000);browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=browser.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:'+str(server.server_port)+'/');page.evaluate(bootstrap)
  page.evaluate('()=>fixture.open()');expect(page.locator('[data-code-region=helpers]')).to_have_count(1);parameters('long firstNative, long secondNative');page.locator('[data-code-save]').click();assert page.evaluate('()=>fixture.state.commits.length')>0,page.locator('[data-code-error]').inner_text();plan=json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'));assert plan['signature']['args']==[{'name':'firstNative','type':'long'},{'name':'secondNative','type':'long'}]and plan['contract']==page.evaluate('()=>fixture.contract')and plan['text']==page.evaluate('()=>fixture.text')and plan['helpers']==page.evaluate('()=>fixture.helpers');checked('explicit own-node value role preserves original source bytes and parent contract; compiler authority separately requires compatible manual source')
  page.evaluate('()=>{fixture.state.drafts={};fixture.open()}');parameters('long firstNative, long secondNative');body('return checked(firstNative-secondNative); // 직접 선택한 변환 😀\n');draft=page.evaluate('()=>fixture.state.drafts.body');page.reload();page.evaluate(bootstrap);page.evaluate('()=>fixture.open()');assert header()=='public long Invoke(long firstNative, long secondNative)';page.locator('[data-code-save]').click();plan=json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'));assert plan['text']==draft['text']and plan['signature']['args']==[{'name':'firstNative','type':'long'},{'name':'secondNative','type':'long'}]and plan['beforeSignature']['args'][0]['name']=='firstNative'and plan['contract']==page.evaluate('()=>fixture.contract');checked('fresh renderer restores explicit own-value/body/helper draft with original node signature and separate public contract')
  page.evaluate('(v)=>{fixture.state.saved={body:v};fixture.state.drafts={};fixture.open()}',plan);assert header()=='public long Invoke(long firstNative, long secondNative)';page.locator('[data-code-save]').click();assert json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'))==plan;checked('Code Save reentry before first owner Save retains exact own ABI/source/flow plan')
  for bad in ['double firstNative, double secondNative','long firstNative, float secondNative','long firstNative, ref double secondNative','long renamedNative, double secondNative','double firstNative, long secondNative','long secondNative, double firstNative','long firstNative, out long secondNative','ref long firstNative, long secondNative','long firstNative, ref long renamedNative','long firstNative','']:
   page.evaluate('()=>{fixture.state.saved={};fixture.state.drafts={};fixture.open()}');parameters(bad);count=page.evaluate('()=>fixture.state.commits.length');page.locator('[data-code-save]').click();expect(page.locator('[data-code-error]')).to_be_visible();assert page.evaluate('()=>fixture.state.commits.length')==count and page.evaluate('()=>fixture.state.drafts.body.parameters')==bad;page.locator('[data-code-cancel]').click();checked('guarded own-node value editor retains rejected input '+bad)
  page.evaluate('()=>{fixture.state.drafts={};fixture.row.editableNativeNames=false;fixture.row.editableNativeTypes=[];fixture.row.removableNativeInputs=[];fixture.row.editableNativeOrder=false;fixture.row.editableNativeRefs=[];fixture.open()}');expect(page.locator('[data-code-region=parameters]')).to_have_count(0);before=page.locator('[data-code-source]').input_value();parameters('long inferred, long secondNative');assert page.locator('[data-code-source]').input_value()==before;page.locator('[data-code-cancel]').click();checked('unselected root/branch/storage contexts retain protected native header')
  page.evaluate('()=>{fixture.row.editableNativeNames=true;fixture.row.editableNativeTypes=["secondNative"];fixture.state.drafts={body:{hash:"f".repeat(64),text:"retained"}};fixture.open()}');expect(page.locator('[role=dialog]')).to_have_count(0);assert page.evaluate('()=>fixture.state.drafts.body.text')=='retained';assert not errors,errors;checked('stale original hash preserves draft without opening a new context');browser.close()
finally:server.shutdown()
record=dict(controlledRenderer=True,actualEngine=False,checks=checks,evidence=str(case));(case/'evidence.json').write_text(json.dumps(record,ensure_ascii=False,indent=2));print(json.dumps(record,ensure_ascii=False))

